SELECT CASE WHEN p.price >= 910 THEN 'high' WHEN p.price >= 270 THEN 'mid' ELSE 'low' END AS price_bucket, MONTH(p.launch_date) AS launch_month, MIN(ss.sale_date) AS first_sale_date FROM store_sales ss FULL OUTER JOIN products p ON ss.product_id = p.id LEFT JOIN stores s ON ss.store_id = s.id WHERE ss.store_id IN (1, 2, 5) GROUP BY CASE WHEN p.price >= 910 THEN 'high' WHEN p.price >= 270 THEN 'mid' ELSE 'low' END, MONTH(p.launch_date) ORDER BY price_bucket;
